import{_ as i,o as e,c as a,a2 as t}from"./chunks/framework.CeXt7FPx.js";const n="/tiffin/screenshots/share-light.png",o="/tiffin/screenshots/share-dark.png",g=JSON.parse('{"title":"Sharing a site","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sharing.md","filePath":"guide/sharing.md"}'),h={name:"guide/sharing.md"};function r(l,s,p,d,k,u){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="sharing-a-site" tabindex="-1">Sharing a site <a class="header-anchor" href="#sharing-a-site" aria-label="Permalink to &quot;Sharing a site&quot;">​</a></h1><p><code>tiffin share</code> gives a site a public <code>https://….trycloudflare.com</code> address, through a Cloudflare quick tunnel: no account, nothing to configure, no port opened on your network. Send it to a client, open it on your phone, or point a webhook at it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # or, in its folder: tiffin share</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # what&#39;s shared</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unshare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # or: tiffin unshare --all</span></span></code></pre></div><p>The first share downloads <code>cloudflared</code>. In the app, the <strong>Share</strong> screen has all three ways of sharing (a public address, your own domain, your network) and lists what is shared; each site on the Projects screen has a <strong>Share</strong> button too, and the tray lists what&#39;s shared.</p><p><img src="`+n+'" alt="The Share screen: a public address, your own domain, your network" class="shot light-only" loading="lazy"><img src="'+o+`" alt="The Share screen: a public address, your own domain, your network" class="shot dark-only" loading="lazy"></p><h2 id="what-visitors-see" tabindex="-1">What visitors see <a class="header-anchor" href="#what-visitors-see" aria-label="Permalink to &quot;What visitors see&quot;">​</a></h2><ul><li><strong>That one site only:</strong> not your other sites, not Tiffin.</li><li><strong>Your app sees a real HTTPS request for the public address,</strong> so Laravel&#39;s <code>url()</code> and <code>asset()</code> build working links with no setup. Links built from a hard-coded <code>APP_URL</code> still point at <code>.test</code>.</li><li><strong>Anyone with the address can use the site,</strong> and change whatever it lets them change, until you stop sharing. Shares end when tiffind stops, and are never restarted by themselves.</li></ul><p>Cloudflare offers quick tunnels for trying things out, with no uptime promise and request limits: fine for showing work, not for hosting.</p><h2 id="on-your-network" tabindex="-1">On your network <a class="header-anchor" href="#on-your-network" aria-label="Permalink to &quot;On your network&quot;">​</a></h2><p>To try a site on your phone or another computer on the same Wi-Fi, share it with your local network instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # http://192.168.1.20:8800, say</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> share</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # everything shared, public and on the network</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unshare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span></span></code></pre></div><p>Each site gets a port of its own (from 8800) on every network interface, serving that site alone over plain HTTP; the app sees the address the visitor used, so its links work there. Anyone on the network can open it until you stop sharing or tiffind stops. The first time, your firewall may ask whether tiffind may accept connections: allow it on private networks only.</p><p>In the app, a site&#39;s ⋯ menu has <strong>Share on your network…</strong>: it shows a QR code to scan with your phone, and the site&#39;s row says where it is shared until you stop.</p><h2 id="on-your-own-domain" tabindex="-1">On your own domain <a class="header-anchor" href="#on-your-own-domain" aria-label="Permalink to &quot;On your own domain&quot;">​</a></h2><p>A quick tunnel&#39;s address changes every time. For the same address every time, such as <code>https://shop.example.com</code>, use a named tunnel. You need a Cloudflare account (the free plan is enough) with your domain on it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # log in, in a browser, and pick the domain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # the tunnel, on your account</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # serve shop.test there (adds the DNS record)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # start serving</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # the login, the tunnel and its routes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiffin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tunnel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span></code></pre></div><ul><li><strong>One tunnel serves every routed site.</strong> Routing or unrouting a site while the tunnel is up takes effect at once.</li><li><strong>Existing DNS records are left alone:</strong> <code>route</code> refuses a hostname that already has one, unless you add <code>--overwrite</code>.</li><li><strong>Removing a route</strong> (<code>tiffin tunnel unroute shop</code>) or the tunnel (<code>tiffin tunnel delete</code>) leaves its DNS records on your account. Remove them on Cloudflare&#39;s dashboard.</li><li><strong>The tunnel runs only when you start it,</strong> until <code>tiffin tunnel down</code> or tiffind stops, like any share. Visitors get the same view as with <code>tiffin share</code>: only that site, over HTTPS, at the public address.</li></ul><p>In the app, a site&#39;s ⋯ menu has <strong>Serve on your domain…</strong>. It walks you through logging in, creating the tunnel and giving the site its hostname, and starts the tunnel. The <strong>Your domain</strong> card on the Projects screen then starts and stops the tunnel, and each routed site shows its hostname.</p><p>Tiffin keeps the Cloudflare login and the tunnel&#39;s credentials in its own data folder, readable only by you. It never reads or changes <code>~/.cloudflared</code>.</p>`,19)])])}const y=i(h,[["render",r]]);export{g as __pageData,y as default};
